package com.bank.flow;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Finds cells that drain to BOTH pools by reverse multi-source DFS.
public class LiquidityFlowAnalyzer {

    private static final Logger log = Logger.getLogger(LiquidityFlowAnalyzer.class.getName());

    private int rows, cols;
    private int[][] grid;

    public List<int[]> cellsReachingBoth(int[][] heights) {
        this.grid = heights;
        this.rows = heights.length;
        this.cols = heights[0].length;
        boolean[][] pacific = new boolean[rows][cols];
        boolean[][] atlantic = new boolean[rows][cols];

        for (int c = 0; c < cols; c++) {
            dfs(0, c, pacific, Integer.MIN_VALUE);           // top → Pacific
            dfs(rows - 1, c, atlantic, Integer.MIN_VALUE);   // bottom → Atlantic
        }
        for (int r = 0; r < rows; r++) {
            dfs(r, 0, pacific, Integer.MIN_VALUE);           // left → Pacific
            dfs(r, cols - 1, atlantic, Integer.MIN_VALUE);   // right → Atlantic
        }

        List<int[]> result = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (pacific[r][c] && atlantic[r][c]) {
                    result.add(new int[]{r, c});
                }
            }
        }
        log.info("Cells draining to both pools: " + result.size());
        return result;
    }

    private void dfs(int r, int c, boolean[][] ocean, int prevHeight) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) return;
        if (ocean[r][c]) return;                 // already marked
        if (grid[r][c] < prevHeight) return;     // reverse flow: must be >=
        ocean[r][c] = true;
        dfs(r + 1, c, ocean, grid[r][c]);
        dfs(r - 1, c, ocean, grid[r][c]);
        dfs(r, c + 1, ocean, grid[r][c]);
        dfs(r, c - 1, ocean, grid[r][c]);
    }
}
