package com.bank.flow;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class FlowDemo {

    private static final Logger log = Logger.getLogger(FlowDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Liquidity Drains to Both Pools");
        int[][] heights = {
            {1, 2, 2, 3, 5},
            {3, 2, 3, 4, 4},
            {2, 4, 5, 3, 1},
            {6, 7, 1, 4, 5},
            {5, 1, 1, 2, 4}
        };
        LiquidityFlowAnalyzer analyzer = new LiquidityFlowAnalyzer();
        analyzer.cellsReachingBoth(heights);
    }
}
